edits.find:
case Persistence.after_message(acc, message, acc.context) do
  :ok -> {:cont, {:ok, acc}}
  {:error, reason} -> {:halt, {:error, reason}}
end

edits.replace:
case Persistence.after_message(acc, message, acc.context) do
  :ok -> {:cont, {:ok, acc}}
  {:error, _reason} -> {:cont, {:ok, acc}}
end
